  + '\n'
  + '    onChange,\n'
  + '  } = props;\n'
  + '\n'
  + '  const theme = useTheme();\n'
  + '\n'
  + '  const mainRef = useRef<HTMLButtonElement | null>(null);\n'
  + '\n'
  + '  const [selectedOptionValue, setSelectedOptionValue] = useState<string | null>(\n'
  + '    value,\n'
  + '  );\n'
  + '  const showLabel = selectedOptionValue\n'
  + '    ? options.find((o) => o.value === selectedOptionValue)?.label\n'
  + '    : null;\n'
  + '\n'
  + '  const [mainWidth, setMainWidth] = useState(0);\n'
  + '\n'
  + '  useEffect(() => {\n'
  + '    if (value === selectedOptionValue) return;\n'
  + '    setSelectedOptionValue(value ?? null);\n'
  + '  }, [value, selectedOptionValue]);\n'
  + '\n'
  + '  const mainStyle = {\n'
  + '    "--select-font-size": theme.tokens.inputBaseMdFontSize,\n'
  + '    "--select-line-height": theme.tokens.inputBaseMdLineHeight,\n'
  + '\n'
  + '    "--select-main-height": theme.tokens.inputBaseMdHeight,\n'
  + '    "--select-main-border-color": theme.tokens.inputBaseDefaultBorderColor,\n'
  + '    "--select-main-border-radius": theme.tokens.inputBaseBorderRadius,\n'
  + '    "--select-main-placeholder-color": theme.tokens.inputBasePlaceholderColor,\n'
  + '\n'
  + '    "--select-main-disabled-color": theme.colors.gray["600"],\n'
  + '    "--select-main-disabled-bg-color": theme.colors.gray["000"],\n'
  + '    "--select-main-disabled-border-color": theme.colors.gray["200"],\n'
  + '  };\n'
  + '\n'
  + '  const listStyle = {\n'
  + '    "--select-font-size": theme.tokens.inputBaseMdFontSize,\n'
  + '    "--select-line-height": theme.tokens.inputBaseMdLineHeight,\n'
  + '\n'
  + '    "--select-list-width": `${mainWidth}px`,\n'
  + '    "--select-list-border-color": theme.tokens.inputBaseDefaultBorderColor,\n'
  + '    "--select-list-border-radius": theme.tokens.inputBaseBorderRadius,\n'
  + '\n'
  + '    "--select-item-hover-bg-color": theme.colors.gray["000"],\n'
  + '  };\n'
  + '\n'
  + '  useLayoutEffect(() => {\n'
  + '    const main = mainRef.current;\n'
  + '    if (main) {\n'
  + '      setMainWidth(main.offsetWidth);\n'
  + '    }\n'
  + '  }, []);\n'
  + '\n'
  + '  return (\n'
  + '    <Popover>\n'
  + '      <Popover.Trigger\n'
  + '        render={({ setRef, onToggle }) => (\n'
  + '          <button\n'
  + '            ref={(el) => {\n'
  + '              setRef(el);\n'
  + '              mainRef.current = el;\n'
  + '            }}\n'
  + '            className={styles.selectMain}\n'
  + '            style={mainStyle as CSSProperties}\n'
  + '            onClick={() => !disabled && onToggle()}\n'
  + '            data-value-picked={selectedOptionValue == null ? "false" : "true"}\n'
  + '            data-disabled={disabled ? "true" : "false"}\n'
  + '            type="button"\n'
  + '            role="combobox"\n'
  + '            aria-haspopup="listbox"\n'
  + '            aria-expanded="false"\n'
  + '          >\n'
  + '            <span style={{ flex: 1 }}>\n'
