  + '            </span>\n'
  + '            <span className={styles.selectIcon}>\n'
  + '              <ChevronsUpDown size="62.5%" />\n'
  + '            </span>\n'
  + '          </button>\n'
  + '        )}\n'
  + '      />\n'
  + '      <Popover.Portal\n'
  + '        onClickOutside={({ closePortal }) => closePortal()}\n'
  + '        render={({ setRef, togglePortal, isOpen, floatingStyles }) =>\n'
  + '          isOpen && (\n'
  + '            <ul\n'
  + '              ref={setRef}\n'
  + '              className={styles.selectList}\n'
  + '              style={{ ...listStyle, ...floatingStyles }}\n'
  + '            >\n'
  + '              {options.map((option) => {\n'
  + '                const handleClick = () => {\n'
  + '                  togglePortal();\n'
  + '\n'
  + '                  if (!disabled) {\n'
  + '                    setSelectedOptionValue(option.value);\n'
  + '                    onChange?.(option.value);\n'
  + '                  }\n'
  + '                };\n'
  + '                return (\n'
  + '                  <li key={option.value} className={styles.selectItem}>\n'
  + '                    <button\n'
  + '                      type="button"\n'
  + '                      className={styles.selectItemButton}\n'
  + '                      onClick={handleClick}\n'
  + '                      onKeyDown={(e) => {\n'
  + '                        if (e.key === "Enter" || e.key === " ") {\n'
  + '                          e.preventDefault();\n'
  + '                          handleClick();\n'
  + '                        }\n'
  + '                      }}\n'
  + '                      tabIndex={0}\n'
  + '                    >\n'
  + '                      {option.label}\n'
  + '                    </button>\n'
  + '                  </li>\n'
  + '                );\n'
  + '              })}\n'
  + '            </ul>\n'
  + '          )\n'
  + '        }\n'
  + '      />\n'
  + '    </Popover>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'Select.displayName = "Select";\n'
  + '\n'
  + 'export { Select };\n'
